# Upstream null can arrive as NA or "", so tests treat both alike.
is_null_value <- function(x) is.na(x) | x == ""

# ---- IP non-starter scenarios (#184) ----
# End of the last snapshot generated by data-raw/simulate_longitudinal_data.R:
# gsm.datasim dates it at month end (2012-03-31) and generates 28 days from there.
as_of_date <- as.Date("2012-04-28")

enrolled_subj <- function() lSource$Raw_SUBJ[lSource$Raw_SUBJ$enrollyn %in% "Y", ]

# Enrolled subjects' STUDCOMP rows, with their IP non-starter status.
enrolled_studcomp <- function() {
  subj <- enrolled_subj()
  sc <- lSource$Raw_STUDCOMP
  sc$status <- subj$drv_ip_nonstarter_status[match(sc$subjid, subj$subjid)]
  sc[!is.na(sc$status), ]
}

